{{ config(materialized='table') }}

with
quarantined as (
    select
        classification_type_code,
        classification_value_code,
        classification_value_name,
        sort_order,
        is_unknown,
        violation_00,
        violation_01
    from {{ ref("reference__investment_classification_value__checked") }}
),
violations as (
    select
        'classification_type_code_not_null' as rule_name,
        classification_type_code,
        classification_value_code,
        classification_value_name,
        sort_order,
        is_unknown
    from quarantined
    where violation_00

    union all

    select
        'classification_value_code_not_null' as rule_name,
        classification_type_code,
        classification_value_code,
        classification_value_name,
        sort_order,
        is_unknown
    from quarantined
    where violation_01
)

select
    rule_name,
    classification_type_code,
    classification_value_code,
    classification_value_name,
    sort_order,
    is_unknown
from violations
